package io.github.athene.data

import android.content.Context
import androidx.room.Dao
import androidx.room.Database
import androidx.room.Entity
import androidx.room.PrimaryKey
import androidx.room.Query
import androidx.room.Room
import androidx.room.RoomDatabase

// Read-only course content shipped as assets/content.db, generated by tools/build_content.py.
// Table layouts here must match the SCHEMA in that script.

@Entity(tableName = "language")
data class Language(
    /** Two-letter code, e.g. "es". */
    @PrimaryKey val code: String,
    val name: String,
    val nativeName: String,
    val flag: String,
    /** BCP-47 tag used for speech, e.g. "es-ES". */
    val locale: String,
)

/** Something to learn: a word, a starter phrase or a sentence. */
@Entity(tableName = "item")
data class Item(
    /** Stable across content rebuilds, e.g. "es:w:casa". User progress is keyed by it. */
    @PrimaryKey val id: String,
    val lang: String,
    /** "word", "phrase" or "sentence". */
    val kind: String,
    /** In the language being learned. */
    val text: String,
    /** Pronunciation in kana, for languages that need it. */
    val reading: String?,
    /** In English. */
    val meaning: String,
    /** Other accepted English meanings, one per line. */
    val altMeanings: String,
    /** Part of speech and gender for words, e.g. "noun, feminine". */
    val note: String,
    /** For phrases and sentences: one "word<TAB>hint" line per word. */
    val tokens: String,
) {
    val isSentence: Boolean get() = kind == KIND_SENTENCE

    val meanings: List<String> get() = listOf(meaning) + altMeanings.lines().filter { it.isNotBlank() }

    /** Whether the language is written without spaces, so that words can only be told apart through [tokens]. */
    val unspaced: Boolean get() = lang in UNSPACED

    /** The words of a phrase or sentence as written, in order; empty when they were not recorded. */
    val surfaces: List<String> get() = tokens.lines().map { it.substringBefore('\t') }.filter { it.isNotEmpty() }

    /** Lower-cased word to its hint, for the words that have one. */
    val hints: Map<String, String>
        get() = tokens.lines().mapNotNull { line ->
            val (word, hint) = line.split('\t').let { it[0] to it.getOrElse(1) { "" } }
            if (hint.isBlank()) null else word.lowercase() to hint
        }.toMap()

    companion object {
        const val KIND_WORD = "word"
        const val KIND_PHRASE = "phrase"
        const val KIND_SENTENCE = "sentence"
        private val UNSPACED = setOf("ja")
    }
}

@Entity(tableName = "unit")
data class CourseUnit(
    @PrimaryKey val id: String,
    val lang: String,
    val ord: Int,
    val title: String,
    val summary: String,
)

@Entity(tableName = "lesson")
data class Lesson(
    @PrimaryKey val id: String,
    val unitId: String,
    val lang: String,
    /** Position in the whole course, starting at 1. */
    val ord: Int,
    val summary: String,
)

@Entity(tableName = "lesson_item", primaryKeys = ["lessonId", "ord"])
data class LessonItem(
    val lessonId: String,
    val ord: Int,
    val itemId: String,
)

@Dao
interface ContentDao {
    @Query("SELECT * FROM language ORDER BY name")
    suspend fun languages(): List<Language>

    @Query("SELECT * FROM language WHERE code = :code")
    suspend fun language(code: String): Language?

    @Query("SELECT * FROM unit WHERE lang = :lang ORDER BY ord")
    suspend fun units(lang: String): List<CourseUnit>

    @Query("SELECT * FROM lesson WHERE lang = :lang ORDER BY ord")
    suspend fun lessons(lang: String): List<Lesson>

    @Query("SELECT * FROM lesson WHERE id = :id")
    suspend fun lesson(id: String): Lesson?

    @Query("SELECT item.* FROM item JOIN lesson_item ON lesson_item.itemId = item.id WHERE lesson_item.lessonId = :lessonId ORDER BY lesson_item.ord")
    suspend fun lessonItems(lessonId: String): List<Item>

    /** Words and phrases taught in a range of lessons; the pool wrong answers are drawn from. */
    @Query(
        "SELECT item.* FROM item JOIN lesson_item ON lesson_item.itemId = item.id " +
            "JOIN lesson ON lesson.id = lesson_item.lessonId " +
            "WHERE lesson.lang = :lang AND lesson.ord BETWEEN :fromOrd AND :toOrd AND item.kind != 'sentence'",
    )
    suspend fun shortItemsInLessons(lang: String, fromOrd: Int, toOrd: Int): List<Item>

    @Query("SELECT * FROM item WHERE id IN (:ids)")
    suspend fun items(ids: List<String>): List<Item>

    @Query("SELECT lesson.ord FROM lesson JOIN lesson_item ON lesson_item.lessonId = lesson.id WHERE lesson_item.itemId = :itemId LIMIT 1")
    suspend fun lessonOrdOf(itemId: String): Int?
}

@Database(
    entities = [Language::class, Item::class, CourseUnit::class, Lesson::class, LessonItem::class],
    version = 3, // keep in step with DB_VERSION in tools/build_content.py
    exportSchema = false,
)
abstract class ContentDatabase : RoomDatabase() {
    abstract fun dao(): ContentDao

    companion object {
        fun open(context: Context): ContentDatabase =
            Room.databaseBuilder(context, ContentDatabase::class.java, "content.db")
                .createFromAsset("content.db")
                // Content is read-only, so a new version simply replaces the old copy.
                .fallbackToDestructiveMigration(dropAllTables = true)
                .build()
    }
}
